design.css:
/* Navigator look: the desktop player copied from Navigator's media player (components/ui/media-player.tsx,
   global-media-player.tsx, player-mobile.css, arc/foundation.css). Values are Navigator's own. */
[data-slot="player.controls"][data-variant="desktop"] {
  --nav-ease-out: cubic-bezier(.23, 1, .32, 1);
  --nav-ghost-hover: oklch(26% 0 0);
  --nav-primary: oklch(0.922 0 0);
}
/* Navigator draws no shade at the top: only its Back circle. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.top"] {
  background: none;
}
/* Controls: px-6 pb-4 with a from-black/80 to-transparent shade behind them. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.bottom"] {
  padding: 48px 24px 16px;
  background: linear-gradient(to top, rgb(0 0 0 / .8), transparent);
}
/* Title: text-3xl, semibold, line-height 1.3, tracking -.01em, no text shadow. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.heading"] {
  padding-top: 0;
  text-shadow: none;
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.title"] {
  font-family: var(--font-heading);
  font-size: 30px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -.01em;
  color: #fff;
}
/* Meta line: text-sm white/60, 6px under the title (gap-1.5). */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.episode"] {
  margin-top: 6px;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.4;
  color: rgb(255 255 255 / .6);
}
/* "Ends at 9:41 PM": text-sm white/70 (drawn with player.endTime). */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.endtime"] {
  font-size: 14px;
  color: rgb(255 255 255 / .7);
}
/* Seek bar: a 9px pill clipped to 6px (inset 1.5px) that opens to the full 9px while dragging, over
   100ms ease-out. Track white/20, buffered white/30, played white, hover white/20. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar"] > div > div:has(> [data-part="player.seekbar.track"]) {
  height: 9px;
  border-radius: 9999px;
  clip-path: inset(1.5px 0 1.5px 0 round 9999px);
  transition: clip-path 100ms var(--nav-ease-out);
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar"]:has([data-scrubbing]) > div > div:has(> [data-part="player.seekbar.track"]) {
  clip-path: inset(0 0 0 0 round 9999px);
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar"] > div > div > div {
  height: 100%;
  transition: none;
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar.track"] { background: rgb(255 255 255 / .2); }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar.buffer"] { background: rgb(255 255 255 / .3); }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar.buffer"] + div:not([data-part]) { background: rgb(255 255 255 / .2); }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar.fill"] { background: #fff; }
/* Toolbar: one row, 8px gaps; transport and actions flattened so every control can be ordered. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] {
  margin-top: 0;
  gap: 8px;
}
[data-slot="player.controls"][data-variant="desktop"] :is([data-part="player.transport"], [data-part="player.actions"]) {
  display: contents;
}
/* Left: Play, Next episode, back 10 s, forward 10 s, volume, time. Right: audio and subtitles,
   framing, settings, picture-in-picture, full screen. Navigator has none of the rest. */
[data-slot="player.controls"][data-variant="desktop"] [data-control="play"] { order: 1; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="next"] { order: 2; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="rewind"] { order: 3; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="forward"] { order: 4; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :has(> [data-control="volume"]) { order: 5; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.time"][data-variant="default"] { order: 6; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :has(> [data-control="tracks"]) { order: 10; margin-left: auto; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="fit"] { order: 11; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :has(> [data-control="options"]) { order: 12; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="pip"] { order: 13; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="fullscreen"] { order: 14; }
/* Ghost icon buttons: 36px, radius 12px, 16px icons, hover --surface-muted, 200ms ease-in-out.
   :where() keeps these at the specificity of the per-button rules below, which then win. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] :where([data-part="player.control"], [data-part="button"][data-control]) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  color: #fff;
  background: transparent;
  transition: color 200ms ease-in-out, background-color 200ms ease-in-out;
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] :where([data-part="player.control"], [data-part="button"][data-control]):hover {
  background: var(--nav-ghost-hover);
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] :where([data-part="player.control"], [data-part="button"][data-control]) svg {
  width: 16px;
  height: 16px;
}
/* Play and the volume trigger are 32px (size-8). */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] :is([data-control="play"], [data-control="volume"]) {
  width: 32px;
  height: 32px;
}
/* Next episode: a small text button (h-8, px-3, gap-2, text-sm medium) with an outline skip icon. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] [data-control="next"] {
  width: auto;
  height: 32px;
  gap: 8px;
  padding: 0 12px;
  white-space: nowrap;
}
[data-slot="player.controls"][data-variant="desktop"] [data-control="next"] svg { fill: none; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="next"]::after {
  content: "Next episode";
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: -.01em;
}
/* Time: text-sm, white/80, tabular figures in the UI font. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.time"][data-variant="default"] {
  margin-left: 0;
  font-family: var(--ui-font);
  font-size: 14px;
  color: rgb(255 255 255 / .8);
  font-variant-numeric: tabular-nums;
}
/* Volume: the slider opens to 64px beside the trigger, in the primary colour. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :has(> [data-control="volume"]):is(:hover, :focus-within) [data-part="player.volume"] {
  width: 64px;
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.volume"] {
  accent-color: var(--nav-primary);
}
/* Last, so the button rules above cannot show them again. */
[data-slot="player.controls"][data-variant="desktop"] :is([data-control="previous"], [data-control="restart"], [data-control="comments"], [data-control="screenshot"], [data-control="bookmark"], [data-control="episodes"]),
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :has(> [data-control="cast"]),
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :has(> [data-control^="subtitle-"]),
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] > span:not([data-part]),
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.control.step"] {
  display: none;
}
/* Loading screens (Theme API 8), copied from Navigator. Values are Navigator's own; motion is plain CSS. */
/* Title page loading (Navigator components/media-page/loading.tsx): hidden for 180 ms so a quick load never
   flashes it, then a transparent 19rem hero (min(62vh, 40rem) from 48rem), the content pulled up 6rem
   (13.5rem), a 2/3 poster clamp(12rem, 56vw, 15rem) on muted/30 and pulsing accent bars. izumi already has the
   card's poster, so it shows with Navigator's 300 ms artwork reveal. */
[data-slot="loading.title"] { animation: nl-wait 180ms step-end; transition: opacity 300ms cubic-bezier(.23, 1, .32, 1); }
[data-slot="loading.title"][data-state="done"] { opacity: 0; }
@keyframes nl-wait { from { visibility: hidden; } }
[data-part="nl-page"] { overflow: hidden; }
[data-part="nl-hero"] { height: 19rem; flex: none; }
[data-part="nl-content"] { margin-top: -6rem; padding: 1.5rem 1rem 0; gap: 2rem; align-items: start; flex-wrap: wrap; }
[data-part="nl-poster"] { width: clamp(12rem, 56vw, 15rem) !important; flex: none; border-radius: .5rem; background: hsl(var(--muted) / .3); }
[data-part="nl-poster"] img { animation: nl-reveal 300ms cubic-bezier(.23, 1, .32, 1) backwards; }
@keyframes nl-reveal { from { opacity: 0; } }
[data-part="nl-lines"] { flex: 1; min-width: 16rem; gap: .75rem; }
[data-part^="nl-bar"] { background: hsl(var(--accent)); border-radius: .375rem; animation: nl-pulse 2s cubic-bezier(.4, 0, .6, 1) infinite; animation-delay: var(--loading-elapsed); }
[data-part="nl-bar-title"] { height: 3rem; width: 75%; }
[data-part="nl-bar-badges"] { height: 1.5rem; width: 10rem; }
[data-part="nl-bar-a"] { height: 6rem; }
[data-part="nl-bar-b"] { height: 7rem; }
@keyframes nl-pulse { 50% { opacity: .5; } }
@media (min-width: 48rem) {
  [data-part="nl-hero"] { height: min(62vh, 40rem); }
  [data-part="nl-content"] { margin-top: -13.5rem; padding-top: 2rem; padding-inline: 2rem; }
}

/* Episode loading (Navigator global-media-player.tsx + player-loading-wordmark.module.css): black, the
   backdrop at brightness .75, a gradient from the bottom, the logo breathing in the middle, the title,
   the episode and a runtime and year line bottom left, and a 16 px ring under them. */
[data-slot="loading.episode"] { background: #000; }
[data-part="nv-root"] { height: 100%; }
[data-part="nv-art"] img { object-fit: cover; filter: brightness(.75); }
[data-part="nv-scrim"] { background: linear-gradient(to top, rgb(0 0 0 / .8), rgb(0 0 0 / .2) 50%, transparent); }
[data-part="nv-mark"] { display: flex; align-items: center; justify-content: center; padding: 0 2rem; z-index: 2;
  animation: nv-appear 240ms cubic-bezier(.23, 1, .32, 1) both; animation-delay: var(--loading-elapsed); }
[data-part="nv-logo"] { width: min(66vw, 48rem); height: 18vh; opacity: .85;
  animation: nv-breathe 2880ms cubic-bezier(.65, 0, .35, 1) infinite; animation-delay: var(--loading-elapsed); }
[data-part="nv-logo"] img { object-fit: contain; filter: drop-shadow(0 10px 28px rgb(0 0 0 / .85)); }
[data-part="nv-mark-text"] { color: #fff; font-size: clamp(1.5rem, 4vw, 3rem); font-weight: 600; text-align: center; text-wrap: balance; }
[data-part="nv-copy"] { align-self: end; gap: .375rem; padding: 0 max(1.5rem, env(safe-area-inset-right)) calc(1.75rem + 1.25rem + .375rem) max(1.5rem, env(safe-area-inset-left)); color: #fff; min-width: 0; }
[data-part="nv-title"] { font-size: 1.875rem; font-weight: 600; line-height: 1.3; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
[data-part="nv-series"] { font-size: .875rem; color: rgb(255 255 255 / .75); }
[data-part="nv-meta"] { gap: .75rem; font-size: .875rem; color: rgb(255 255 255 / .6); }
@keyframes nv-appear { from { opacity: 0; scale: .97; } }
@keyframes nv-breathe { 0%, 100% { opacity: .72; scale: .985; } 50% { opacity: .95; scale: 1.015; } }
@media (min-width: 48rem) { [data-part="nv-logo"] { width: min(52vw, 48rem); height: 22vh; } }
@media (max-width: 40rem) { [data-part="nv-title"] { font-size: 1.5rem; line-height: 1.4; white-space: normal; text-wrap: balance; } }
/* The ring and the slow-source line follow the screen in the markup: a 16 px ring bottom left, white/70. */
[data-slot="loading.episode"][data-state="loading"] ~ * [data-part="spinner"][data-variant="player"] {
  --theme-player-spinner-size: 16px; --theme-player-spinner-stroke: 1.5px;
  position: absolute; left: max(1.5rem, env(safe-area-inset-left)); bottom: calc(1.75rem + 2px); border-top-color: rgb(255 255 255 / .7) !important; }
[data-slot="loading.episode"] ~ [data-part="play.loader.detail"] { top: auto; bottom: 1.75rem; left: calc(max(1.5rem, env(safe-area-inset-left)) + 24px); right: auto; margin: 0; padding: 0; text-align: start; font-size: .875rem; font-weight: 500; color: rgb(255 255 255 / .7); }
/* Back: a 36 px ghost circle 16 px from the corner. */
[data-slot="loading.episode"] ~ [data-part="play.connecting.back"] { left: 1rem; top: 1rem; width: 36px; height: 36px; background: transparent; color: #fff; }
[data-slot="loading.episode"] ~ [data-part="play.connecting.back"]:hover { background: rgb(255 255 255 / .1); }
